<?php
declare(strict_types=1);header('Content-Type: application/json; charset=utf-8');require __DIR__.'/inc/db.php';require __DIR__.'/inc/order_service.php';
try{require_login();if(current_user()['role']!=='customer')throw new RuntimeException('Only customer accounts can place orders.');$token=(string)($_SERVER['HTTP_X_CSRF_TOKEN']??'');if($token===''||!hash_equals(csrf_token(),$token)){http_response_code(419);throw new RuntimeException('Your session expired. Refresh checkout and try again.');}$payload=json_decode((string)file_get_contents('php://input'),true,32,JSON_THROW_ON_ERROR);$order=create_normal_order($pdo,$payload,user_id());echo json_encode(['success'=>true,'order_number'=>$order['order_number'],'order_id'=>$order['id'],'total'=>$order['total'],'redirect'=>'order_details.php?id='.$order['id']]);}catch(Throwable $e){error_log('Cash order failed: '.$e->getMessage());if(http_response_code()<400)http_response_code(422);$message=$e instanceof PDOException?'Unable to place the order. Please try again.':$e->getMessage();echo json_encode(['success'=>false,'message'=>$message]);}
